package com.nexodb.ui;

import static com.nexodb.util.I18n.tr;
import com.nexodb.tools.SqlProjectService;
import com.nexodb.util.SqlFiles;
import javax.swing.*;
import javax.swing.border.EmptyBorder;
import javax.swing.event.*;
import javax.swing.tree.*;
import java.awt.*;
import java.awt.event.*;
import java.nio.file.*;
import java.util.*;
import java.util.List;
import java.util.concurrent.Callable;
import java.util.function.Consumer;

/** Local SQL project workspace with safe file editing and command-based Git integration. */
public final class SqlProjectPanel extends JPanel {
    private record ProjectNode(Path relative,boolean directory,String state){@Override public String toString(){if(relative==null)return "";Path name=relative.getFileName();return name==null?relative.toString():name.toString();}}
    private final SqlProjectService project;private final Consumer<Path> queryOpener;
    private final DefaultMutableTreeNode rootNode=new DefaultMutableTreeNode();private final DefaultTreeModel treeModel=new DefaultTreeModel(rootNode);private final JTree tree=new JTree(treeModel);
    private final SqlEditorPane editor=new SqlEditorPane();private final JTextArea diff=new JTextArea();private final GitHistoryPanel history;private final JTabbedPane details=new JTabbedPane();
    private final JTextArea consoleOutput=new JTextArea();private final JTextField consoleInput=new JTextField();
    private final JLabel status=new JLabel(" "),branch=new JLabel(),remote=new JLabel(),filePath=new JLabel("Ningún archivo abierto");private final JButton save=button("Guardar"),openQuery=button("Abrir en consulta"),refresh=button("Actualizar"),stage=button("Preparar"),unstage=button("Quitar de preparados"),fileHistory=button("Historial");
    private Path current;private String diskHash="";private boolean loading,dirty,busy;

    public SqlProjectPanel(SqlProjectService project,Consumer<Path> queryOpener){
        super(new BorderLayout(6,6));this.project=project;this.queryOpener=queryOpener;this.history=new GitHistoryPanel(project::commitDetails,project::commitChanges,project::commitPatch,project::fileAtCommit);setBorder(new EmptyBorder(8,8,8,8));
        JToolBar files=new JToolBar();files.setFloatable(false);files.add(new JLabel(project.name()+"   "));files.add(button("Nuevo SQL",this::newSql));files.add(button("Nueva carpeta",this::newFolder));files.add(button("Renombrar",this::rename));files.add(button("Eliminar",this::delete));files.add(refresh);files.addSeparator();files.add(save);files.add(openQuery);add(files,BorderLayout.NORTH);
        tree.setRootVisible(true);tree.setShowsRootHandles(true);tree.setCellRenderer(new Renderer());tree.addTreeSelectionListener(e->selectionChanged());tree.addMouseListener(new MouseAdapter(){public void mouseClicked(MouseEvent e){if(e.getClickCount()==2)openSelected();}});
        editor.getDocument().addDocumentListener(new DocumentListener(){private void changed(){if(!loading){dirty=true;updateActions();}}public void insertUpdate(DocumentEvent e){changed();}public void removeUpdate(DocumentEvent e){changed();}public void changedUpdate(DocumentEvent e){}});
        int shortcut=GraphicsEnvironment.isHeadless()?KeyEvent.CTRL_DOWN_MASK:Toolkit.getDefaultToolkit().getMenuShortcutKeyMaskEx();editor.getInputMap().put(KeyStroke.getKeyStroke(KeyEvent.VK_S,shortcut),"save-project-sql");editor.getActionMap().put("save-project-sql",new AbstractAction(){public void actionPerformed(ActionEvent e){save();}});
        diff.setEditable(false);diff.setFont(new Font(Font.MONOSPACED,Font.PLAIN,13));JButton code=button("Código",()->details.setSelectedIndex(0));fileHistory.addActionListener(e->loadFileHistory());JToolBar fileBar=new JToolBar();fileBar.setFloatable(false);filePath.setFont(filePath.getFont().deriveFont(Font.BOLD));fileBar.add(filePath);fileBar.add(Box.createHorizontalGlue());fileBar.add(code);fileBar.add(fileHistory);JPanel sqlView=new JPanel(new BorderLayout());sqlView.add(fileBar,BorderLayout.NORTH);sqlView.add(new JScrollPane(editor));details.addTab("SQL",sqlView);details.addTab(tr("Cambios Git"),new JScrollPane(diff));details.addTab(tr("Historial Git"),history);details.addTab(tr("Consola Git"),gitConsole());JSplitPane split=new JSplitPane(JSplitPane.HORIZONTAL_SPLIT,new JScrollPane(tree),details);split.setDividerLocation(285);split.setResizeWeight(.18);add(split);
        JToolBar git=new JToolBar();git.setFloatable(false);git.add(new JLabel("Git: "));git.add(branch);git.add(new JLabel("   GitHub: "));git.add(remote);git.addSeparator();git.add(button("Inicializar Git",this::initGit));git.add(stage);git.add(unstage);git.add(button("Preparar todo",this::stageAll));git.add(button("Commit…",this::commit));git.add(button("Identidad Git…",this::identity));git.add(button("Ver historial",this::loadHistory));git.add(button("Historial del archivo",this::loadFileHistory));git.add(button("Consola Git",()->details.setSelectedIndex(3)));JToolBar online=new JToolBar();online.setFloatable(false);online.add(button("Conectar GitHub…",this::connectGithub));online.add(button("Repositorio…",this::configureRemote));online.add(button("Traer",this::pull));online.add(button("Enviar",this::push));online.add(button("Sincronizar",this::sync));JPanel bars=new JPanel(new GridLayout(0,1));bars.add(git);bars.add(online);JPanel footer=new JPanel(new BorderLayout(6,4));footer.add(bars,BorderLayout.NORTH);footer.add(status);add(footer,BorderLayout.SOUTH);
        refresh.addActionListener(e->refresh());save.addActionListener(e->save());openQuery.addActionListener(e->openInQuery());stage.addActionListener(e->gitForSelected(true));unstage.addActionListener(e->gitForSelected(false));refresh();
    }
    public Path root(){return project.root();}
    public String projectName(){return project.name();}
    public void importSql(Path relative,String sql){if(busy){status.setText(tr("Esperando a que termine la operación Git para guardar la definición…"));javax.swing.Timer wait=new javax.swing.Timer(150,null);wait.addActionListener(e->{if(!busy){((javax.swing.Timer)e.getSource()).stop();importSql(relative,sql);}});wait.start();return;}try{Path target=project.root().resolve(relative).normalize();if(Files.exists(target)&&!Confirmations.ask(this,"Actualizar definición en Git",relative+"\n"+tr("El archivo ya existe. ¿Reemplazarlo con la definición actual del servidor?")))return;if(Objects.equals(current,relative)&&!leaveCurrent())return;project.write(relative,sql);status.setText(tr("Definición agregada al proyecto: ")+relative);refresh();}catch(Exception error){showError(error);}}
    public boolean canClose(){if(!dirty)return true;Object[] options={tr("Guardar"),tr("Descartar"),tr("Cancelar")};int answer=JOptionPane.showOptionDialog(DialogPosition.owner(this),tr("Hay cambios sin guardar en ")+current+".",tr("Cerrar proyecto SQL"),JOptionPane.DEFAULT_OPTION,JOptionPane.WARNING_MESSAGE,null,options,options[0]);if(answer==0)return save();return answer==1;}
    private static JButton button(String text){return UiLanguage.text(new JButton(tr(text)),UiLanguage.key(text));}
    private static JButton button(String text,Runnable action){JButton button=button(text);button.addActionListener(e->action.run());return button;}
    private JComponent gitConsole(){consoleOutput.setEditable(false);consoleOutput.setFont(new Font(Font.MONOSPACED,Font.PLAIN,13));consoleOutput.setText("Consola Git segura del proyecto. Ejemplos:\n  git status\n  git diff\n  git add archivo.sql\n  git commit -m \"resolver conflicto\"\n  git merge --abort\n\nNo ejecuta comandos del sistema ni permite reset --hard o clean.\n");JButton run=button("Ejecutar",this::runConsoleCommand),clear=button("Limpiar",()->consoleOutput.setText(""));JComboBox<String> examples=new JComboBox<>(new String[]{tr("Comandos frecuentes…"),"git status","git diff","git log --oneline --decorate -20","git merge --abort","git rebase --abort","git add --all"});examples.addActionListener(e->{if(examples.getSelectedIndex()>0)consoleInput.setText(Objects.toString(examples.getSelectedItem(),""));});consoleInput.addActionListener(e->runConsoleCommand());JPanel command=new JPanel(new BorderLayout(6,0));command.setBorder(new EmptyBorder(6,6,6,6));command.add(new JLabel("git>"),BorderLayout.WEST);command.add(consoleInput);JPanel actions=new JPanel(new FlowLayout(FlowLayout.RIGHT,4,0));actions.add(examples);actions.add(run);actions.add(clear);command.add(actions,BorderLayout.EAST);JPanel panel=new JPanel(new BorderLayout());panel.add(command,BorderLayout.NORTH);panel.add(new JScrollPane(consoleOutput));return panel;}
    private void updateActions(){boolean file=current!=null&&!busy;save.setEnabled(file&&dirty);openQuery.setEnabled(file);fileHistory.setEnabled(file&&project.isGitRepository());ProjectNode selected=selected();boolean selection=selected!=null&&selected.relative()!=null&&!selected.relative().toString().isBlank();stage.setEnabled(selection&&project.isGitRepository());unstage.setEnabled(selection&&project.isGitRepository());editor.setEditable(file&&!busy);}
    private ProjectNode selected(){TreePath path=tree.getSelectionPath();if(path==null)return null;Object value=((DefaultMutableTreeNode)path.getLastPathComponent()).getUserObject();return value instanceof ProjectNode node?node:null;}
    private void selectionChanged(){ProjectNode node=selected();if(node!=null&&!node.directory())load(node.relative());}
    private void openSelected(){ProjectNode node=selected();if(node!=null&&!node.directory())load(node.relative());}
    private boolean leaveCurrent(){if(!dirty)return true;int answer=JOptionPane.showConfirmDialog(DialogPosition.owner(this),tr("Guardar los cambios de ")+current+"?",tr("Proyecto SQL"),JOptionPane.YES_NO_CANCEL_OPTION,JOptionPane.WARNING_MESSAGE);if(answer==JOptionPane.CANCEL_OPTION||answer==JOptionPane.CLOSED_OPTION)return false;return answer!=JOptionPane.YES_OPTION||save();}
    private void load(Path relative){if(Objects.equals(relative,current)||!leaveCurrent())return;setBusy(true,tr("Abriendo ")+relative+"…");new SwingWorker<SqlFiles.Loaded,Void>(){protected SqlFiles.Loaded doInBackground()throws Exception{return project.read(relative);}protected void done(){try{SqlFiles.Loaded loaded=get();current=project.root().relativize(loaded.path());filePath.setText(current.toString());filePath.setToolTipText(project.root().resolve(current).toString());diskHash=loaded.diskHash();loading=true;editor.restoreText(loaded.text());editor.setCaretPosition(0);loading=false;dirty=false;details.setSelectedIndex(0);status.setText(tr("Archivo abierto: ")+current);}catch(Exception error){showError(rootCause(error));}finally{loading=false;setBusy(false,null);updateActions();}}}.execute();}
    private boolean save(){if(current==null||busy)return false;try{Path target=project.root().resolve(current);if(!diskHash.isBlank()&&Files.exists(target)&&!SqlFiles.diskHash(target).equals(diskHash)){int answer=JOptionPane.showConfirmDialog(DialogPosition.owner(this),tr("El archivo cambió fuera de AdisDB. ¿Sobrescribirlo con el contenido del editor?"),tr("Conflicto de archivo"),JOptionPane.YES_NO_OPTION,JOptionPane.WARNING_MESSAGE);if(answer!=JOptionPane.YES_OPTION)return false;}diskHash=project.write(current,editor.getText());dirty=false;status.setText(tr("Guardado: ")+current);updateActions();refresh();return true;}catch(Exception error){showError(error);return false;}}
    private void openInQuery(){if(current==null||dirty&&!save())return;queryOpener.accept(project.root().resolve(current));}
    private void refresh(){setBusy(true,tr("Leyendo proyecto y estado Git…"));new SwingWorker<List<SqlProjectService.Entry>,Void>(){protected List<SqlProjectService.Entry> doInBackground()throws Exception{return project.entries();}protected void done(){try{List<SqlProjectService.Entry> entries=get();rebuild(entries);branch.setText(project.isGitRepository()?Objects.toString(project.branch(),tr("sin rama")):tr("no inicializado"));String url=project.remoteUrl();remote.setText(url.isBlank()?tr("sin repositorio"):shortRemote(url));remote.setToolTipText(url);if(current!=null&&project.isGitRepository())loadDiff(current);status.setText(entries.size()+tr(" elementos · ")+project.root());}catch(Exception error){showError(rootCause(error));}finally{setBusy(false,null);}}}.execute();}
    private void rebuild(List<SqlProjectService.Entry> entries){rootNode.removeAllChildren();rootNode.setUserObject(new ProjectNode(Path.of(""),true,""));Map<Path,DefaultMutableTreeNode> nodes=new HashMap<>();nodes.put(Path.of(""),rootNode);for(SqlProjectService.Entry entry:entries){Path relative=entry.relative(),parent=relative.getParent()==null?Path.of(""):relative.getParent();DefaultMutableTreeNode parentNode=ensureDirectory(parent,nodes);DefaultMutableTreeNode node=nodes.get(relative);if(node==null){node=new DefaultMutableTreeNode(new ProjectNode(relative,entry.directory(),entry.gitStatus()));nodes.put(relative,node);parentNode.add(node);}else node.setUserObject(new ProjectNode(relative,entry.directory(),entry.gitStatus()));}treeModel.reload();for(int i=0;i<tree.getRowCount();i++)tree.expandRow(i);selectCurrent();}
    private DefaultMutableTreeNode ensureDirectory(Path path,Map<Path,DefaultMutableTreeNode> nodes){DefaultMutableTreeNode existing=nodes.get(path);if(existing!=null)return existing;Path parent=path.getParent()==null?Path.of(""):path.getParent();DefaultMutableTreeNode node=new DefaultMutableTreeNode(new ProjectNode(path,true,""));ensureDirectory(parent,nodes).add(node);nodes.put(path,node);return node;}
    private void selectCurrent(){if(current==null)return;Enumeration<?> all=rootNode.depthFirstEnumeration();while(all.hasMoreElements()){DefaultMutableTreeNode node=(DefaultMutableTreeNode)all.nextElement();if(node.getUserObject() instanceof ProjectNode value&&current.equals(value.relative())){tree.setSelectionPath(new TreePath(node.getPath()));return;}}}
    private Path folderForNew(){ProjectNode node=selected();if(node==null||node.relative()==null)return Path.of("");return node.directory()?node.relative():Objects.requireNonNullElse(node.relative().getParent(),Path.of(""));}
    private void newSql(){if(!LicenseGate.ensure(this))return;String name=JOptionPane.showInputDialog(DialogPosition.owner(this),tr("Nombre del nuevo archivo SQL:"),"consulta.sql");if(name==null)return;try{Path created=project.createSql(folderForNew().resolve(name));refresh();load(created);}catch(Exception error){showError(error);}}
    private void newFolder(){if(!LicenseGate.ensure(this))return;String name=JOptionPane.showInputDialog(DialogPosition.owner(this),tr("Nombre de la nueva carpeta:"),"scripts");if(name==null)return;try{project.createFolder(folderForNew().resolve(name));refresh();}catch(Exception error){showError(error);}}
    private void rename(){ProjectNode node=selected();if(node==null||node.relative()==null||node.relative().toString().isBlank()||!leaveCurrent())return;String name=JOptionPane.showInputDialog(DialogPosition.owner(this),tr("Nuevo nombre:"),node.relative().getFileName());if(name==null)return;try{Path old=node.relative(),renamed=project.rename(old,name);if(old.equals(current)){current=renamed;diskHash=SqlFiles.diskHash(project.root().resolve(renamed));}refresh();}catch(Exception error){showError(error);}}
    private void delete(){ProjectNode node=selected();if(node==null||node.relative()==null||node.relative().toString().isBlank())return;if(node.relative().equals(current)&&!leaveCurrent())return;if(!Confirmations.ask(this,"Eliminar del proyecto",node.relative()+"\n"+tr("Esta acción elimina el archivo local. Git podrá recuperarlo si ya tenía un commit. ¿Continuar?")))return;try{project.delete(node.relative());if(node.relative().equals(current)){current=null;filePath.setText(tr("Ningún archivo abierto"));filePath.setToolTipText(null);diskHash="";dirty=false;loading=true;editor.restoreText("");loading=false;}refresh();updateActions();}catch(Exception error){showError(error);}}
    private void initGit(){if(!LicenseGate.ensure(this))return;runGit(tr("Inicializando Git…"),project::initGit,true);}
    private void gitForSelected(boolean add){ProjectNode node=selected();if(node==null||node.relative()==null||node.relative().toString().isBlank())return;runGit(add?tr("Preparando cambio…"):tr("Quitando de preparados…"),()->add?project.stage(node.relative()):project.unstage(node.relative()),true);}
    private void stageAll(){runGit(tr("Preparando cambios…"),project::stageAll,true);}
    private void commit(){if(!LicenseGate.ensure(this))return;String message=JOptionPane.showInputDialog(DialogPosition.owner(this),tr("Mensaje del commit:"));if(message==null)return;runGit(tr("Creando commit…"),()->{SqlProjectService.GitResult staged=project.stageAll();return staged.ok()?project.commit(message):staged;},true);}
    private void identity(){JTextField name=new JTextField(),email=new JTextField();JPanel form=new JPanel(new GridLayout(0,2,8,8));form.add(new JLabel(tr("Nombre")));form.add(name);form.add(new JLabel(tr("Correo")));form.add(email);if(JOptionPane.showConfirmDialog(DialogPosition.owner(this),form,tr("Identidad Git del proyecto"),JOptionPane.OK_CANCEL_OPTION)!=JOptionPane.OK_OPTION)return;runGit(tr("Guardando identidad Git…"),()->project.configureIdentity(name.getText(),email.getText()),false);}
    private void connectGithub(){if(!LicenseGate.ensure(this))return;if(!project.githubLoginAvailable()){showError(new IllegalStateException(tr("Instala Git Credential Manager o GitHub CLI para conectar la cuenta mediante el navegador.")));return;}if(!Confirmations.ask(this,"Conectar cuenta GitHub",tr("Se abrirá el inicio de sesión seguro de GitHub. AdisDB no verá ni guardará tu contraseña o token. ¿Continuar?")))return;runGit(tr("Esperando autenticación de GitHub en el navegador…"),project::githubLogin,false);}
    private void configureRemote(){if(!LicenseGate.ensure(this))return;if(!project.isGitRepository()){status.setText(tr("Inicializa Git primero."));return;}JTextField url=new JTextField(project.remoteUrl(),34),target=new JTextField(project.branch().isBlank()?"main":project.branch(),14);JPanel form=new JPanel(new GridLayout(0,2,8,8));form.add(new JLabel(tr("URL del repositorio")));form.add(url);form.add(new JLabel(tr("Rama")));form.add(target);JTextArea note=new JTextArea(project.githubAccounts());note.setEditable(false);note.setOpaque(false);note.setRows(3);note.setLineWrap(true);note.setWrapStyleWord(true);form.add(new JLabel(tr("Cuenta GitHub")));form.add(note);if(JOptionPane.showConfirmDialog(DialogPosition.owner(this),form,tr("Configurar repositorio GitHub"),JOptionPane.OK_CANCEL_OPTION)!=JOptionPane.OK_OPTION)return;runGit(tr("Configurando repositorio remoto…"),()->project.configureRemote(url.getText(),target.getText()),true);}
    private void pull(){if(!readyForNetwork())return;runGit(tr("Descargando cambios de GitHub…"),project::pull,true);}
    private void push(){if(!readyForNetwork())return;runGit(tr("Enviando commits a GitHub…"),project::push,true);}
    private void sync(){if(!readyForNetwork())return;runGit(tr("Sincronizando con GitHub…"),project::sync,true);}
    private boolean readyForNetwork(){if(!LicenseGate.ensure(this)||!project.isGitRepository())return false;if(dirty&&!save())return false;if(project.remoteUrl().isBlank()){status.setText(tr("Configura primero el repositorio remoto."));return false;}return true;}
    private void loadDiff(Path relative){if(!project.isGitRepository())return;runText(tr("Leyendo diferencias…"),()->project.diff(relative),text->{diff.setText(text.isBlank()?tr("Sin cambios para este archivo."):text);diff.setCaretPosition(0);});}
    private void loadHistory(){loadHistory(null);}
    private void loadFileHistory(){if(current==null){status.setText(tr("Abre o selecciona un archivo SQL para ver su historial completo."));return;}loadHistory(current);}
    private void loadHistory(Path file){if(!project.isGitRepository()){status.setText(tr("Inicializa Git primero."));return;}String label=file==null?tr("Historial completo del proyecto"):tr("Historial completo del archivo · ")+file;setBusy(true,file==null?tr("Construyendo historial visual de ramas y fusiones…"):tr("Buscando todas las versiones del archivo…"));new SwingWorker<List<SqlProjectService.GitGraphLine>,Void>(){protected List<SqlProjectService.GitGraphLine> doInBackground()throws Exception{return project.historyGraph(file);}protected void done(){try{history.setFocusPath(file==null?"":file.toString());history.setScope(label);history.setHistory(get());details.setSelectedIndex(2);status.setText(file==null?tr("Historial completo del proyecto actualizado."):tr("Historial completo del archivo actualizado: ")+file);}catch(Exception error){showError(rootCause(error));}finally{setBusy(false,null);}}}.execute();}
    private void runConsoleCommand(){if(busy)return;if(!project.isGitRepository()){status.setText(tr("Inicializa Git primero."));return;}String command=consoleInput.getText().trim();if(command.isBlank())return;details.setSelectedIndex(3);consoleOutput.append("\n$ "+command+"\n");consoleInput.selectAll();setBusy(true,tr("Ejecutando comando Git del proyecto…"));new SwingWorker<SqlProjectService.GitResult,Void>(){protected SqlProjectService.GitResult doInBackground()throws Exception{return project.runConsole(command);}protected void done(){try{SqlProjectService.GitResult result=get();consoleOutput.append((result.output().isBlank()?"(sin salida)":result.output())+"\n");consoleOutput.setCaretPosition(consoleOutput.getDocument().getLength());status.setText(result.ok()?tr("Comando Git completado."):tr("Git devolvió un error; revisa la consola."));}catch(Exception error){Throwable cause=rootCause(error);consoleOutput.append("ERROR: "+cause.getMessage()+"\n");status.setText(cause.getMessage());}finally{setBusy(false,null);refresh();}}}.execute();}
    private void runGit(String message,Callable<SqlProjectService.GitResult> work,boolean reload){setBusy(true,message);new SwingWorker<SqlProjectService.GitResult,Void>(){protected SqlProjectService.GitResult doInBackground()throws Exception{return work.call();}protected void done(){boolean refreshAfter=false;try{SqlProjectService.GitResult result=get();status.setText(result.output().isBlank()?(result.ok()?tr("Operación Git completada."):tr("Git no completó la operación.")):result.output());if(!result.ok())JOptionPane.showMessageDialog(DialogPosition.owner(SqlProjectPanel.this),result.output(),tr("Git"),JOptionPane.WARNING_MESSAGE);refreshAfter=reload;}catch(Exception error){showError(rootCause(error));}finally{setBusy(false,null);if(refreshAfter)refresh();}}}.execute();}
    private void runText(String message,Callable<String> work,Consumer<String> done){setBusy(true,message);new SwingWorker<String,Void>(){protected String doInBackground()throws Exception{return work.call();}protected void done(){try{done.accept(get());}catch(Exception error){showError(rootCause(error));}finally{setBusy(false,null);}}}.execute();}
    private void setBusy(boolean value,String message){busy=value;if(message!=null)status.setText(message);tree.setEnabled(!value);refresh.setEnabled(!value);updateActions();}
    private void showError(Throwable error){status.setText(error.getMessage());JOptionPane.showMessageDialog(DialogPosition.owner(this),error.getMessage(),tr("Proyecto SQL"),JOptionPane.ERROR_MESSAGE);}
    private static Throwable rootCause(Throwable error){Throwable result=error;while(result.getCause()!=null&&result.getCause()!=result)result=result.getCause();return result;}
    private static String shortRemote(String url){String value=url.replace("https://github.com/","").replace("git@github.com:","");if(value.endsWith(".git"))value=value.substring(0,value.length()-4);return value.length()>34?value.substring(0,31)+"…":value;}
    private final class Renderer extends DefaultTreeCellRenderer{public Component getTreeCellRendererComponent(JTree tree,Object value,boolean selected,boolean expanded,boolean leaf,int row,boolean focus){JLabel label=(JLabel)super.getTreeCellRendererComponent(tree,value,selected,expanded,leaf,row,focus);Object user=((DefaultMutableTreeNode)value).getUserObject();if(user instanceof ProjectNode node){String state=node.state(),caption=node.relative()!=null&&node.relative().toString().isBlank()?project.name():node.toString();label.setText(caption+(state.isBlank()?"":"   ["+state+"]"));label.setIcon(IconFactory.of(node.directory()?IconFactory.Kind.FOLDER:IconFactory.Kind.SQL,16));if(!selected&&!state.isBlank())label.setForeground(state.contains("?")?ThemeManager.color(0xB45309,0xFBBF24):ThemeManager.color(0xB91C1C,0xFCA5A5));}return label;}}
}
